CREATE OR REPLACE PROCEDURE restore_baseline IS
BEGIN
    DELETE FROM "Institution";
    INSERT INTO "Institution" SELECT * FROM inst_bak;
    DELETE FROM "building";
    INSERT INTO "building" SELECT * FROM building_bak;
END restore_baseline;

CREATE OR REPLACE PROCEDURE run_test(
    p_tc  NUMBER,
    p_enr NUMBER,
    p_iid VARCHAR2,
    p_h   NUMBER,
    p_st  VARCHAR2
) IS
    diff NUMBER;
BEGIN
    restore_baseline;
    sp_orig(p_enr, p_iid, p_h, p_st);
    DELETE FROM cmp_institution;
    INSERT INTO cmp_institution SELECT * FROM "Institution";
    DELETE FROM cmp_building;
    INSERT INTO cmp_building SELECT * FROM "building";

    restore_baseline;
    sp_opt(p_enr, p_iid, p_h, p_st);

    SELECT COUNT(*) INTO diff FROM (
        SELECT * FROM "Institution" MINUS SELECT * FROM cmp_institution
        UNION ALL
        SELECT * FROM cmp_institution MINUS SELECT * FROM "Institution"
    );
    IF diff > 0 THEN
        INSERT INTO test_log VALUES (p_tc, 'INSTITUTION DIFF ' || diff);
    END IF;

    SELECT COUNT(*) INTO diff FROM (
        SELECT * FROM "building" MINUS SELECT * FROM cmp_building
        UNION ALL
        SELECT * FROM cmp_building MINUS SELECT * FROM "building"
    );
    IF diff > 0 THEN
        INSERT INTO test_log VALUES (p_tc, 'BUILDING DIFF ' || diff);
    END IF;
END run_test;

BEGIN
    run_test(1, 2, '1', 145, '701 North Franklin Street');
    run_test(2, 10, '1', 160, '315 John F. Kennedy Boulevard');
    run_test(3, 20, '1', 204, '905 Franklin Street');
    run_test(4, 30, '1', 160, '315 John F. Kennedy Boulevard');
    run_test(5, 40, '1', 100, '701 North Franklin Street');
    run_test(6, 22, '7', 537, '201 North Franklin Street');
    run_test(7, 18, '0', 120, 'nonexistent');
    run_test(8, 2, 'nonexistent', 150, 'nonexistent');
    run_test(9, 34, 'Z', 458, '400 North Tampa Street');
    run_test(10, 650, 'Z', 100, '101 East Kennedy Boulevard');
    run_test(11, 0, NULL, NULL, NULL);
    run_test(12, 100, '1', 160, '315 John F. Kennedy Boulevard');
END;

BEGIN
    run_test(13, 0, '1', 50, 'nonexistent');
    run_test(14, 14, '1', 145, '701 North Franklin Street');
    run_test(15, 19, '1', 160, '315 John F. Kennedy Boulevard');
    run_test(16, 23, '1', 204, '905 Franklin Street');
    run_test(17, 29, '1', 280, '655 North Franklin Street');
    run_test(18, 34, '1', 458, '400 North Tampa Street');
    run_test(19, 35, '1', 100, '701 North Franklin Street');
    run_test(20, 1000, '7', 160, '315 John F. Kennedy Boulevard');
    run_test(21, 1200, 'ZZZ', 145, '701 North Franklin Street');
END;

